package com.fitlife.personal.controller;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/personais") public class PersonalController{private final JdbcTemplate jdbc;public PersonalController(JdbcTemplate j){jdbc=j;}
 @GetMapping public List<Map<String,Object>> listar(@RequestParam(required=false)String modalidade,@RequestParam(required=false)String cidade){String sql="SELECT id,nome,titulo,modalidades,disponibilidade,cidade,estado FROM personal WHERE 1=1";List<Object>a=new ArrayList<>();if(modalidade!=null&&!modalidade.isBlank()){sql+=" AND LOWER(modalidades) LIKE ?";a.add("%"+modalidade.toLowerCase()+"%");}if(cidade!=null&&!cidade.isBlank()){sql+=" AND LOWER(cidade) LIKE ?";a.add("%"+cidade.toLowerCase()+"%");}sql+=" ORDER BY id";return jdbc.queryForList(sql,a.toArray());}
 @PostMapping("/{id}/contatos")public Map<String,Object> contato(@PathVariable long id,@RequestBody Map<String,Object>d){Long user;try{user=Long.valueOf(String.valueOf(d.get("usuarioId")));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Usuário inválido.");}Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM personal WHERE id=?",Integer.class,id);if(count==null||count==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal não encontrado.");jdbc.update("INSERT INTO contato_personal(usuario_id,personal_id) VALUES(?,?) ON DUPLICATE KEY UPDATE criado_em=CURRENT_TIMESTAMP",user,id);return Map.of("enviado",true,"personalId",id);}}
